package com.vstream.Vidiserver;

/** The page editor served at /site-editor.js (made from site-editor.js by the update script - do not edit by hand). */
final class SiteEditorJs {

    private SiteEditorJs() {
    }

    static final String JS = ""
            + "// Memoryq site editor: the super-admin changes the website's words in place. Each part of the page that can be\n"
            + "// changed gets a small pencil (in \"Edit page\" mode). Save shows the change at once - no reload.\n"
            + "(function () {\n"
            + "  'use strict';\n"
            + "  var token = null;\n"
            + "  try { token = localStorage.getItem('vs_token'); } catch (e) { }\n"
            + "  if (!token) { return; }\n"
            + "  var editing = null, mode = false, pens = [], bar = null, box = null, before = '';\n"
            + "  function api(path, form) {\n"
            + "    return fetch(path, { method: form ? 'POST' : 'GET', headers: Object.assign({ 'Authorization': 'Bearer ' + token },\n"
            + "      form ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}), body: form ? new URLSearchParams(form).toString() : undefined })\n"
            + "      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (d) { return { ok: r.ok, data: d }; }); })\n"
            + "      .catch(function () { return { ok: false, data: { error: 'Cannot reach the server' } }; });\n"
            + "  }\n"
            + "  function css() {\n"
            + "    var s = document.createElement('style');\n"
            + "    s.textContent = '[data-edit].se-on{outline:1px dashed rgba(47,111,237,.55);outline-offset:3px;border-radius:2px}' +\n"
            + "      '[data-edit].se-live{outline:2px solid #2f6fed;outline-offset:3px;background:rgba(47,111,237,.06);border-radius:2px}' +\n"
            + "      '.se-pen{position:absolute;z-index:9998;width:24px;height:24px;border-radius:50%;border:0;background:#2f6fed;color:#fff;font:14px/24px system-ui;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.3);padding:0}' +\n"
            + "      '.se-pen:hover{background:#1d4fc4}' +\n"
            + "      '.se-bar{position:absolute;z-index:9999;display:flex;gap:4px;background:#16202a;padding:5px;border-radius:8px;box-shadow:0 4px 14px rgba(0,0,0,.35);font:13px system-ui}' +\n"
            + "      '.se-bar button{border:0;border-radius:5px;padding:5px 9px;cursor:pointer;background:#2a3542;color:#fff;font:600 13px system-ui}' +\n"
            + "      '.se-bar button.save{background:#2e9e5b}.se-bar button.cancel{background:#6b7a88}' +\n"
            + "      '.se-box{position:fixed;left:14px;bottom:14px;z-index:10000;background:#16202a;color:#fff;border-radius:22px;padding:8px 14px;font:600 13px system-ui;box-shadow:0 4px 14px rgba(0,0,0,.35);cursor:pointer;user-select:none}' +\n"
            + "      '.se-box.on{background:#2f6fed}' +\n"
            + "      '.se-toast{position:fixed;left:50%;bottom:20px;transform:translateX(-50%);z-index:10001;background:#1b1f23;color:#fff;padding:9px 16px;border-radius:8px;font:14px system-ui}';\n"
            + "    document.head.appendChild(s);\n"
            + "  }\n"
            + "  function toast(t) { var d = document.createElement('div'); d.className = 'se-toast'; d.textContent = t; document.body.appendChild(d); setTimeout(function () { d.remove(); }, 2600); }\n"
            + "  function place() {\n"
            + "    pens.forEach(function (p) {\n"
            + "      var r = p.el.getBoundingClientRect();\n"
            + "      var hidden = r.width === 0 && r.height === 0;\n"
            + "      p.btn.style.display = hidden || editing ? 'none' : 'block';\n"
            + "      p.btn.style.left = (window.scrollX + r.right - 4) + 'px';\n"
            + "      p.btn.style.top = (window.scrollY + r.top - 14) + 'px';\n"
            + "    });\n"
            + "    if (bar && editing) {\n"
            + "      var r = editing.getBoundingClientRect();\n"
            + "      bar.style.left = (window.scrollX + Math.max(8, r.left)) + 'px';\n"
            + "      bar.style.top = (window.scrollY + r.top - 46) + 'px';\n"
            + "    }\n"
            + "  }\n"
            + "  function setMode(on) {\n"
            + "    mode = on;\n"
            + "    try { sessionStorage.setItem('se_mode', on ? '1' : ''); } catch (e) { }\n"
            + "    box.className = 'se-box' + (on ? ' on' : '');\n"
            + "    box.innerHTML = on ? '&#9998; Editing the page - click a pencil &middot; Done' : '&#9998; Edit page';\n"
            + "    if (!on && editing) { stop(true); }\n"
            + "    pens.forEach(function (p) { p.btn.remove(); p.el.classList.remove('se-on'); });\n"
            + "    pens = [];\n"
            + "    if (!on) { return; }\n"
            + "    document.querySelectorAll('[data-edit]').forEach(function (el) {\n"
            + "      el.classList.add('se-on');\n"
            + "      var b = document.createElement('button');\n"
            + "      b.className = 'se-pen'; b.type = 'button'; b.title = 'Change this text'; b.innerHTML = '&#9998;';\n"
            + "      b.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); start(el); });\n"
            + "      document.body.appendChild(b);\n"
            + "      pens.push({ el: el, btn: b });\n"
            + "    });\n"
            + "    place();\n"
            + "  }\n"
            + "  function cmd(name, arg) { document.execCommand(name, false, arg); editing && editing.focus(); }\n"
            + "  function start(el) {\n"
            + "    if (editing) { stop(true); }\n"
            + "    editing = el; before = el.innerHTML;\n"
            + "    el.contentEditable = 'true'; el.classList.add('se-live'); el.focus();\n"
            + "    bar = document.createElement('div'); bar.className = 'se-bar';\n"
            + "    var btns = [['B', 'Bold', function () { cmd('bold'); }], ['I', 'Italic', function () { cmd('italic'); }], ['U', 'Underline', function () { cmd('underline'); }],\n"
            + "      ['Link', 'Make the selected words a link', function () { var u = prompt('Link address (https://... or /page):', 'https://'); if (u) { cmd('createLink', u); } }],\n"
            + "      ['Unlink', 'Remove the link', function () { cmd('unlink'); }],\n"
            + "      ['Original', 'Back to the words in the page file', reset],\n"
            + "      ['Cancel', 'Leave it as it was (Esc)', function () { stop(true); }],\n"
            + "      ['Save', 'Save it now (Ctrl+Enter)', save]];\n"
            + "    btns.forEach(function (x) {\n"
            + "      var b = document.createElement('button'); b.type = 'button'; b.textContent = x[0]; b.title = x[1];\n"
            + "      if (x[0] === 'Save') { b.className = 'save'; } if (x[0] === 'Cancel') { b.className = 'cancel'; }\n"
            + "      b.addEventListener('mousedown', function (e) { e.preventDefault(); });\n"
            + "      b.addEventListener('click', x[2]);\n"
            + "      bar.appendChild(b);\n"
            + "    });\n"
            + "    document.body.appendChild(bar);\n"
            + "    place();\n"
            + "  }\n"
            + "  function stop(restore) {\n"
            + "    if (!editing) { return; }\n"
            + "    if (restore) { editing.innerHTML = before; }\n"
            + "    editing.contentEditable = 'false'; editing.classList.remove('se-live');\n"
            + "    editing = null;\n"
            + "    if (bar) { bar.remove(); bar = null; }\n"
            + "    place();\n"
            + "  }\n"
            + "  function save() {\n"
            + "    var el = editing; if (!el) { return; }\n"
            + "    api('/api/admin/content/save', { key: el.getAttribute('data-edit'), html: el.innerHTML }).then(function (r) {\n"
            + "      if (!r.ok) { toast(r.data.error || 'Could not save'); return; }\n"
            + "      before = r.data.html; el.innerHTML = r.data.html; stop(false); toast('Saved - visitors see it now');\n"
            + "    });\n"
            + "  }\n"
            + "  function reset() {\n"
            + "    var el = editing; if (!el || !confirm('Put back the original words of this part?')) { return; }\n"
            + "    api('/api/admin/content/reset', { key: el.getAttribute('data-edit') }).then(function (r) {\n"
            + "      if (!r.ok) { toast(r.data.error || 'Could not do that'); return; }\n"
            + "      before = r.data.html; el.innerHTML = r.data.html; stop(false); toast('Back to the original');\n"
            + "    });\n"
            + "  }\n"
            + "  document.addEventListener('keydown', function (e) {\n"
            + "    if (!editing) { return; }\n"
            + "    if (e.key === 'Escape') { e.preventDefault(); stop(true); }\n"
            + "    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); save(); }\n"
            + "  });\n"
            + "  document.addEventListener('click', function (e) {\n"
            + "    if (mode && e.target.closest && e.target.closest('[data-edit]') && e.target.closest('a')) { e.preventDefault(); } // links do not open while editing the page\n"
            + "  }, true);\n"
            + "  window.addEventListener('scroll', place, { passive: true });\n"
            + "  window.addEventListener('resize', place);\n"
            + "  api('/api/me').then(function (r) {\n"
            + "    if (!r.ok || r.data.role !== 'ADMIN') { return; }\n"
            + "    css();\n"
            + "    box = document.createElement('div'); box.className = 'se-box'; box.title = 'Super-admin: change the words on this page';\n"
            + "    box.addEventListener('click', function () { setMode(!mode); });\n"
            + "    document.body.appendChild(box);\n"
            + "    var on = /[?&]edit=1/.test(location.search);\n"
            + "    try { on = on || sessionStorage.getItem('se_mode') === '1'; } catch (e) { }\n"
            + "    setMode(on);\n"
            + "    setInterval(place, 1000);\n"
            + "  });\n"
            + "})();\n"
            + "\n";
}